async(page)=>{
 const base='http://127.0.0.1:5173/',tag=base.startsWith('http://127')?'local':'public',checks=[],metrics=[],errors=[],cloudCalls=[]
 const check=(ok,label)=>{if(!ok)throw Error(label);checks.push(label)},error=e=>errors.push(e.message),request=r=>{if(/cloudbasegateway|tencentcloudapi|tcb-api/.test(r.url()))cloudCalls.push(r.url())}
 page.on('pageerror',error);page.on('request',request)
 const nav=async(actor,route)=>{await page.goto(base+'?release=price-governance&demo='+actor+'#/'+route);await page.locator('main').waitFor()}
 const shot=async(name)=>page.screenshot({path:'D:/Desktop/小食云记-新网页版/docs/evidence/price-governance-'+tag+'-'+name+'-20261108.png'})
 let failure='',backup
 try{
  await nav('admin','me');backup=await page.evaluate(()=>Object.fromEntries(Object.keys(localStorage).filter(k=>k.startsWith('xsyj-demo:v1:')||k.startsWith('xsyj-draft:demo-')).map(k=>[k,localStorage.getItem(k)])))
  await page.evaluate(()=>localStorage.removeItem('xsyj-draft:demo-admin:new'));await nav('admin','publish')
  const input=page.getByRole('spinbutton',{name:'价格 · 元',exact:true}),plus=page.getByRole('button',{name:'增加1元',exact:true}),minus=page.getByRole('button',{name:'减少1元',exact:true})
  for(const width of [320,390,1440]){await page.setViewportSize({width,height:844});const m=await page.locator('.price-stepper').evaluate(e=>{const r=e.getBoundingClientRect(),i=e.querySelector('input').getBoundingClientRect(),b=e.querySelector('button').getBoundingClientRect();return {rowWidth:r.width,inputWidth:i.width,buttonWidth:b.width,buttonHeight:b.height,overflow:document.documentElement.scrollWidth>innerWidth||e.scrollWidth>e.clientWidth}});check(m.inputWidth<=190&&m.buttonWidth>=44&&m.buttonHeight>=44&&!m.overflow,'短价格框与大按钮在不同屏幕完整显示 '+width);metrics.push({width,...m});if(width===390){await input.fill('15.12');await page.locator('.price-field').scrollIntoViewIfNeeded();await shot('price')}}
  await page.setViewportSize({width:390,height:844});await input.fill('15.12');await plus.click();check(await input.inputValue()==='16.12','单击加1元保留小数且不重复触发');await minus.click();check(await input.inputValue()==='15.12','单击减1元保留小数');await input.press('ArrowUp');check(await input.inputValue()==='16.12','键盘向上也加1元');await input.press('ArrowDown');check(await input.inputValue()==='15.12','键盘向下也减1元');await plus.focus();await page.keyboard.press('Space');check(await input.inputValue()==='16.12','空格可操作按钮且不提交表单')
  await input.fill('10.12');await plus.hover();await page.mouse.down();await page.waitForTimeout(950);await page.mouse.up();const held=Number(await input.inputValue());check(held>=15.12&&Math.round(held*100)%100===12,'长按快速加价且每次保持1元');await page.waitForTimeout(300);check(Number(await input.inputValue())===held,'松手立即停止连续加价')
  await input.fill('50.12');await minus.hover();await page.mouse.down();await page.waitForTimeout(700);await page.getByRole('heading',{name:'价格与口味',exact:true}).hover();await page.mouse.up();const decreased=Number(await input.inputValue());check(decreased<=46.12&&Math.round(decreased*100)%100===12,'长按减价并在移出后松手停止');await page.waitForTimeout(250);check(Number(await input.inputValue())===decreased,'移出松手后金额不再变化')
  await plus.hover();await page.mouse.down();await page.waitForTimeout(500);await page.evaluate(()=>window.dispatchEvent(new Event('blur')));const blurred=await input.inputValue();await page.waitForTimeout(300);await page.mouse.up();check(await input.inputValue()===blurred,'窗口失去焦点停止长按')
  await input.fill('0.01');check(await minus.isDisabled(),'最低价格不减成零');await input.fill('999.99');check(await plus.isDisabled(),'最高价格不超过999.99');await input.fill('999.5');check(await plus.isDisabled(),'不足完整1元的边界不偷偷改变步长');await input.fill('');check(await minus.isDisabled(),'空价格不向下生成无效值');await plus.click();check(await input.inputValue()==='1','空价格从1元开始');await input.fill('15.12');await page.reload();await input.waitFor();check(await input.inputValue()==='15.12','小数价格本机草稿刷新保留')
  await plus.hover();await page.mouse.down();await page.waitForTimeout(500);await page.evaluate(()=>{location.hash='/me'});await page.getByRole('heading',{name:'示例管理员',exact:true}).waitFor();const draft=await page.evaluate(()=>JSON.parse(localStorage.getItem('xsyj-draft:demo-admin:new')).price);await page.waitForTimeout(350);await page.mouse.up();check(await page.evaluate(()=>JSON.parse(localStorage.getItem('xsyj-draft:demo-admin:new')).price)===draft,'切页卸载会停止长按计时器')
  check(await page.getByRole('button',{name:'用户治理',exact:true}).count()===1&&await page.getByRole('button',{name:'用户反馈',exact:true}).count()===0,'管理员底部只保留用户治理');await page.getByRole('button',{name:'用户治理',exact:true}).scrollIntoViewIfNeeded();await shot('me');await page.getByRole('button',{name:'用户治理',exact:true}).click();await page.getByRole('heading',{name:'用户治理',exact:true}).waitFor();check(true,'用户治理入口打开现有管理功能');await page.getByRole('button',{name:'用户',exact:true}).click();await page.getByRole('button',{name:'云朵同学',exact:false}).first().waitFor();check(true,'用户列表仍可查看')
  await nav('student','me');check(await page.getByRole('button',{name:'用户治理',exact:true}).count()===0&&await page.getByRole('button',{name:'用户反馈',exact:true}).count()===0,'普通用户不暴露治理权限或重复入口');await page.getByRole('button',{name:/^互动消息/}).click();await page.getByRole('heading',{name:'互动消息',exact:true}).waitFor();await page.locator('.message-item').first().click();await page.getByRole('heading',{name:'黄焖鸡',exact:true}).waitFor();check(true,'互动消息可定位评论对应的原投稿')
  await nav('student','messages');const first=page.locator('article.message').first();await first.getByRole('button',{name:'标为已读',exact:true}).click();await first.getByText('已读',{exact:true}).waitFor();check(true,'评论提醒可标为已读');await page.getByRole('button',{name:'清除已读',exact:true}).click();await page.getByText('暂时没有记录。',{exact:true}).waitFor();check(true,'已读评论提醒可以清理')
  await page.getByRole('button',{name:'用户反馈',exact:true}).click();const body='入口合并示例：价格支持逐元加减，长按操作后能正常停止。';await page.locator('.feedback-compose textarea').fill(body);await page.getByRole('button',{name:'提交反馈',exact:true}).click();await page.getByText(body,{exact:true}).waitFor();const entry=page.locator('.feedback-entry').filter({hasText:body});await entry.getByRole('button',{name:'补充 / 回复',exact:true}).click();await page.getByPlaceholder('补充情况，或回复对方',{exact:true}).fill('补充示例：手机上按钮容易点到。');await page.getByRole('button',{name:'发送回复',exact:true}).click();await entry.getByText('补充示例：手机上按钮容易点到。',{exact:true}).waitFor();check(true,'移除底部重复入口后仍可从互动消息反馈和补充');await shot('messages-feedback')
  await nav('student','admin');await page.getByText('普通用户没有管理员权限。',{exact:true}).waitFor();check(await page.getByRole('button',{name:'下架投稿',exact:true}).count()===0,'普通用户直接访问治理网址仍受权限保护')
  check(errors.length===0,'无页面运行时错误');check(cloudCalls.length===0,'所有新增案例只操作本机演示，不写真实云端')
 }catch(e){failure=e.message;await shot('failure').catch(()=>{})}finally{
  await page.mouse.up().catch(()=>{});if(backup)await page.evaluate(original=>{for(const k of Object.keys(localStorage))if(k.startsWith('xsyj-demo:v1:')||k.startsWith('xsyj-draft:demo-'))localStorage.removeItem(k);for(const[k,v]of Object.entries(original))localStorage.setItem(k,v)},backup)
  page.off('pageerror',error);page.off('request',request)
 }
 return {base,checks,metrics,errors,cloudCalls,failure}
}
